/** Looks up a verified video. Throws at build time on a typo. */
export function video(id: string): ContentVideo {
  const entry = TABLE[id];
  if (!entry) throw new Error(`D.O.M.S: unknown video id ${id}`);
  return { id, ...entry };
}

export const VIDEO_IDS = Object.keys(TABLE);
